def expected_score(a, b):                                                                                                                                                      # Define function expected_score for reuse.
    return 1 / (1 + 10 ** ((b - a) / 400))                                                                                                                                                      # Send this value back to the caller.
def update_elo(w_elo, l_elo, k=K):                                                                                                                                                      # Define function update_elo for reuse.
    e = expected_score(w_elo, l_elo)                                                                                                                                                      # Assign into 'e'.
    return w_elo + k * (1 - e), l_elo + k * (0 - (1 - e))                                                                                                                                                      # Send this value back to the caller.
elo_overall  = defaultdict(lambda: BASE_ELO)                                                                                                                                                      # Assign into 'elo_overall'.
