    out["loser_1stWon_pct"].append(avg_serve_stat(serve_history_w[lid], 3))                                                                                                                                                      # Append one element to a growing list.
    out["winner_bpSaved_pct"].append(avg_serve_stat(serve_history_w[wid], 4))                                                                                                                                                      # Append one element to a growing list.
